 const movementTable=(rows:Movement[],compact=false)=><div className="table-scroll"><table><thead><tr><th>ITEM</th><th>TYPE</th><th>QUANTITY</th>{!compact&&<th>REASON</th>}<th>TEAM MEMBER</th><th>WHEN</th>{!compact&&<><th>LOCATIONS</th><th>CORRECTION</th></>}</tr></thead><tbody>{rows.map(m=><tr key={m.id}><td><button className="table-name" onClick={()=>{const i=items.find(i=>i.id===m.item_id);if(i)openItem(i)}}>{items.find(i=>i.id===m.item_id)?.name??'Unknown item'}</button></td><td><span className={'movement '+m.kind}>{m.kind==='add'?<ArrowDownLeft size={14}/>:m.kind==='remove'?<ArrowUpRight size={14}/>:<SlidersHorizontal size={14}/>} {m.kind==='add'?'Stock in':m.kind==='remove'?'Stock out':m.kind==='transfer'?'Transfer':m.kind==='return'?'Return':m.kind==='reversal'?'Reversal':'Adjustment'}</span></td><td className={m.delta>=0?'positive':'negative'}>{m.transfer_quantity?m.transfer_quantity:<>{m.delta>0?'+':''}{m.delta}</>}</td>{!compact&&<td>{m.reason??m.note}{m.notes&&<small>{m.notes}</small>}{m.recipient&&<small>Issued to: {m.recipient}</small>}<small>{m.transfer_quantity?`${locations.find(l=>l.id===m.from_location_id)?.name??'Source'} → ${locations.find(l=>l.id===m.to_location_id)?.name??'Destination'}`:`${m.before_quantity} → ${m.after_quantity}`}</small></td>}<td><span className="person-dot">{(members.find(u=>u.id===m.actor_id)?.name??'?').slice(0,1)}</span>{members.find(u=>u.id===m.actor_id)?.name??'Former member'}</td><td className="muted">{new Date(m.created_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</td>{!compact&&<><td>{m.from_location_id&&<small>From: {locations.find(l=>l.id===m.from_location_id)?.name}</small>}{m.to_location_id&&<small>To: {locations.find(l=>l.id===m.to_location_id)?.name}</small>}</td><td>{m.reverses_id?<small>Reverses {m.reverses_id}</small>:movements.some(r=>r.reverses_id===m.id)?<span className="badge archive-badge">Reversed</span>:admin&&<button className="text-button" disabled={!!pendingRequest} onClick={()=>reversePosted(m)}>Reverse</button>}</td></>}</tr>)}{!rows.length&&<tr><td colSpan={compact?5:8} className="empty">No stock movements yet.</td></tr>}</tbody></table></div>;
 if(!authReady)return <div className="login"><RefreshCw/>Loading your workspace…</div>;
